<template><el-card class="permission-matrix" shadow="never"><template #header><div class="permission-matrix__heading"><div><strong>权限配置</strong></div><span>已选择 <b>{{ modelValue.length }}</b> 项</span></div></template><div class="permission-matrix__layout"><el-menu :default-active="activeGroup" class="permission-matrix__menu" @select="activeGroup=$event"><el-menu-item v-for="group in groups" :key="group.key" :index="group.key"><el-icon><component :is="icons[group.icon as keyof typeof icons]||Grid"/></el-icon><span>{{ group.label }}</span><em>{{ selectedCount(group.key) }}/{{ group.actions.length }}</em></el-menu-item></el-menu><section class="permission-matrix__content"><header><el-checkbox :model-value="allSelected" :indeterminate="partSelected" @change="toggleAll">模块全选</el-checkbox><span>{{ currentGroup.label }}</span></header><el-checkbox-group :model-value="modelValue" @update:model-value="emit('update:modelValue',$event as string[])"><div class="permission-matrix__actions"><label v-for="action in currentGroup.actions" :key="action.key"><el-checkbox :value="action.key">{{ action.label }}</el-checkbox></label></div></el-checkbox-group></section></div></el-card></template>
<script setup lang="ts">import{computed,ref}from'vue';import{Grid,Lock,Postcard,Setting,Switch,Upload,User,Wallet}from'@element-plus/icons-vue';import type{PermissionGroup}from'../../types';const props=defineProps<{groups:PermissionGroup[];modelValue:string[]}>();const emit=defineEmits<{(e:'update:modelValue',v:string[]):void}>();const icons={Grid,Lock,Postcard,Setting,Switch,Upload,User,Wallet};const activeGroup=ref(props.groups[0]?.key||'');const currentGroup=computed(()=>props.groups.find(g=>g.key===activeGroup.value)??props.groups[0]);const currentKeys=computed(()=>currentGroup.value.actions.map(a=>a.key));const selectedCurrent=computed(()=>currentKeys.value.filter(k=>props.modelValue.includes(k)));const allSelected=computed(()=>selectedCurrent.value.length===currentKeys.value.length);const partSelected=computed(()=>selectedCurrent.value.length>0&&!allSelected.value);function selectedCount(key:string){const group=props.groups.find(g=>g.key===key);return group?.actions.filter(a=>props.modelValue.includes(a.key)).length??0}function toggleAll(value:unknown){const selected=new Set(props.modelValue);for(const key of currentKeys.value)value?selected.add(key):selected.delete(key);emit('update:modelValue',[...selected])}</script>
<style scoped lang="scss">.permission-matrix{border-color:#dfe8ef;border-radius:15px}.permission-matrix :deep(.el-card__body){padding:0}.permission-matrix__heading{display:flex;align-items:center;justify-content:space-between;gap:16px}.permission-matrix__heading>div{display:grid;gap:4px}.permission-matrix__heading strong{color:#17324f;font-size:16px}.permission-matrix__heading span{color:#718298;font-size:12px}.permission-matrix__heading>b,.permission-matrix__heading>span b{color:#089b91}.permission-matrix__layout{display:grid;min-height:520px;grid-template-columns:230px minmax(0,1fr)}.permission-matrix__menu{border-right:1px solid #dfe8ef}.permission-matrix__menu .el-menu-item{gap:5px}.permission-matrix__menu .el-menu-item em{margin-left:auto;color:#8293a8;font-size:11px;font-style:normal}.permission-matrix__content{padding:20px}.permission-matrix__content>header{display:flex;align-items:center;justify-content:space-between;padding:0 0 15px;border-bottom:1px solid #e5edf3;color:#587087;font-size:13px}.permission-matrix__actions{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;padding-top:18px}.permission-matrix__actions label{padding:13px;border:1px solid #e0e9f0;border-radius:10px;background:#fbfdff}@include narrow{.permission-matrix__actions{grid-template-columns:repeat(2,minmax(0,1fr))}}@include mobile{.permission-matrix__layout{grid-template-columns:1fr}.permission-matrix__menu{display:flex;overflow-x:auto;border-right:0;border-bottom:1px solid #dfe8ef}.permission-matrix__menu .el-menu-item{flex:0 0 auto}.permission-matrix__actions{grid-template-columns:1fr}.permission-matrix__content{padding:15px}}</style>
